<script setup>
const props=defineProps({refreshToken:{type:Number,default:0}})
import {ref,computed,onMounted,watch} from 'vue'
import {request} from '../../shared/api'
import MicIcon from '../../features/voice/MicIcon.vue'
import {useVoiceInput} from '../../features/voice/useVoiceInput'
import {categories,categoryLabel} from '../../shared/categories'
const category=ref('auto'),categoryFilter=ref('all')
const history=ref([])
const tasks=ref([]),text=ref(''),title=ref(''),description=ref(''),message=ref(''),busy=ref(false),draft=ref(null),editing=ref(null),filter=ref('active')
const visible=computed(()=>tasks.value.filter(t=>(filter.value==='all'||(filter.value==='done'?t.completed:!t.completed))&&(categoryFilter.value==='all'||t.category===categoryFilter.value)))
const activeCount=computed(()=>tasks.value.filter(t=>!t.completed).length)
async function refresh(){tasks.value=await request('/todos')}
const {supported,listening,starting,processing,toggle,cancel,recordSeconds}=useVoiceInput({text,onComplete:interpret,onError:value=>message.value=value})
async function run(work){busy.value=true;try{await work();await refresh()}catch(error){message.value=error.message}finally{busy.value=false}}
async function add(){if(!title.value.trim())return;await run(async()=>{const selected=category.value==='auto'?(await request('/todos/classify','POST',{title:title.value,description:description.value})).category:category.value;await request('/todos','POST',{title:title.value,description:description.value,category:selected});title.value='';description.value='';message.value='Задача добавлена.'})}
async function complete(task){await run(()=>request('/todos/'+task.id,'PUT',{title:task.title,description:task.description,category:task.category,completed:!task.completed}))}
async function save(){await run(async()=>{await request('/todos/'+editing.value.id,'PUT',{title:editing.value.title,description:editing.value.description,category:editing.value.category,completed:editing.value.completed});editing.value=null})}
async function remove(task){draft.value={manual:task,note:'Удалить задачу «'+task.title+'»?'}}
async function execute(){if(!draft.value)return;await run(async()=>{if(draft.value.manual)await request('/todos/'+draft.value.manual.id,'DELETE');else await request('/todos/commands/'+draft.value.id+'/execute','POST');draft.value=null;text.value='';message.value='Готово. Список обновлён.'})}
async function interpret(){
 if(busy.value||!text.value.trim())return
 const utterance=text.value.trim()
 if(draft.value && /^(подтверждаю|удаляй|выполни|да)[.! ]*$/i.test(utterance)){await execute();return}
 if(draft.value && /^(отмена|отмени|нет)[.! ]*$/i.test(utterance)){draft.value=null;text.value='';message.value='Отменено.';return}
 busy.value=true;message.value='Разбираю задачи…';draft.value=null
 try{const result=await request('/todos/commands/prepare','POST',{text:utterance,history:history.value});history.value=[...history.value,{role:'user',text:utterance.slice(0,1500)},{role:'assistant',text:result.note.slice(0,1500)}].slice(-8);draft.value=result;message.value=result.note;text.value='';busy.value=false;if(!result.requires_confirmation)await execute()}
 catch(error){message.value=error.message;history.value=[...history.value,{role:'user',text:utterance.slice(0,1500)},{role:'assistant',text:error.message.slice(0,1500)}].slice(-8)}finally{busy.value=false}
}
function mic(){message.value='';toggle()}
function discardRecording(){cancel();text.value='';message.value='Запись отменена. Задачи не добавлены.'}
onMounted(()=>run(refresh))
watch(()=>props.refreshToken,()=>refresh().catch(e=>message.value=e.message))
</script>
<template><main class="todo-app"><header class="todo-heading"><div><span class="todo-eyebrow">ГОЛОСОВОЙ ПЛАНИРОВЩИК</span><h1>Мои задачи</h1><p>{{ activeCount?activeCount+' в работе':'Можно начать с одного дела' }} · без привязки ко времени</p></div><div class="todo-record-actions"><button :class="['todo-mic',{recording:listening}]" :disabled="!supported||busy||processing||starting" @click="mic"><MicIcon/>{{ listening?'Стоп · '+recordSeconds+' с':processing?'Распознаю…':starting?'Микрофон…':'Говорить' }}</button><button v-if="listening||starting||processing" class="cancel-record-button" @click="discardRecording">× Отменить запись</button></div></header>
<section class="todo-capture"><form @submit.prevent="add"><label for="todo-title">Что нужно сделать?</label><div class="todo-add-row"><input id="todo-title" v-model="title" maxlength="200" required placeholder="Например, закончить отчёт" :disabled="busy"><button class="primary-button" :disabled="busy||!title.trim()">Добавить</button></div><textarea v-model="description" aria-label="Описание новой задачи" maxlength="5000" placeholder="Подробности, если нужны…" :disabled="busy"></textarea><label>Категория<select v-model="category" :disabled="busy"><option value="auto">Определить с помощью ИИ</option><option v-for="c in categories" :key="c.value" :value="c.value">{{ c.label }}</option></select></label></form></section>
<section class="todo-voice"><div class="todo-voice-heading"><MicIcon/><strong>{{ listening?'Слушаю · '+recordSeconds+' с':processing?'Распознаю речь…':'Или просто расскажи о делах' }}</strong></div><form @submit.prevent="interpret"><textarea v-model="text" aria-label="Голосовая команда задачам" placeholder="Надо купить продукты, закончить отчёт. В отчёте проверить расчёты…" maxlength="6000" :disabled="busy||listening||processing||starting"></textarea><button class="outline-button" :disabled="busy||listening||processing||starting||!text.trim()">{{ busy?'Обрабатываю…':'Выполнить команду' }}</button></form><p v-if="message" class="todo-message" role="status">{{ message }}</p><section v-if="draft" class="todo-confirm"><p>{{ draft.note }}</p><ul v-if="draft.operations"><li v-for="(op,i) in draft.operations" :key="i">{{ {create:'Добавить',update:'Изменить',delete:'Удалить',complete:'Завершить',reopen:'Вернуть в работу'}[op.action.action] }}: {{ op.action.title||op.snapshot?.title }}</li></ul><button class="primary-button" :disabled="busy" @click="execute">Подтвердить</button><button class="outline-button" :disabled="busy" @click="draft=null;message='Отменено.'">Отмена</button></section></section>
<nav class="todo-filters" aria-label="Фильтр задач"><button :class="{active:filter==='active'}" @click="filter='active'">В работе · {{ activeCount }}</button><button :class="{active:filter==='done'}" @click="filter='done'">Выполнено · {{ tasks.length-activeCount }}</button><button :class="{active:filter==='all'}" @click="filter='all'">Все</button></nav>
<section class="priority-grid" aria-label="Категории задач"><button :class="{selected:categoryFilter==='all'}" @click="categoryFilter='all'">Все категории<span>{{ tasks.filter(t=>filter==='all'||(filter==='done'?t.completed:!t.completed)).length }}</span></button><button v-for="c in categories" :key="c.value" :data-category="c.value" :class="{selected:categoryFilter===c.value}" :aria-pressed="categoryFilter===c.value" @click="categoryFilter=c.value"><strong>{{ c.label }}</strong><small>{{ c.hint }}</small><span>{{ tasks.filter(t=>t.category===c.value&&(filter==='all'||(filter==='done'?t.completed:!t.completed))).length }}</span></button></section><section aria-label="Список задач"><div v-if="!visible.length" class="todo-empty"><span>✓</span><h2>{{ categoryFilter!=='all'?'В этой категории пока нет задач':filter==='done'?'Пока нет завершённых задач':'Здесь будут твои дела' }}</h2><p>Запиши голосом или добавь задачу выше. Дата и время не нужны.</p></div><article v-for="task in visible" :key="task.id" :class="['todo-item',{done:task.completed}]"><input type="checkbox" :checked="task.completed" :disabled="busy" :aria-label="(task.completed?'Вернуть в работу: ':'Выполнить: ')+task.title" @change="complete(task)"><div class="todo-item-body"><strong>{{ task.title }}</strong><span class="priority-badge" :data-category="task.category">{{ categoryLabel(task.category) }}</span><p v-if="task.description">{{ task.description }}</p></div><button class="icon-button" :aria-label="'Изменить: '+task.title" :disabled="busy" @click="editing={...task}">✎</button><button class="icon-button" :aria-label="'Удалить: '+task.title" :disabled="busy" @click="remove(task)">×</button></article></section><footer class="todo-footer"><span class="local-dot"></span>Голосовые команды для твоих дел</footer>
<div v-if="editing" class="modal-backdrop" @click.self="!busy&&(editing=null)"><section class="event-editor" role="dialog" aria-modal="true" aria-label="Изменить задачу"><h2>Изменить задачу</h2><form @submit.prevent="save"><label>Название<input v-model="editing.title" required maxlength="200"></label><label>Описание<textarea v-model="editing.description" maxlength="5000"></textarea></label><label>Категория<select v-model="editing.category"><option v-for="c in categories" :key="c.value" :value="c.value">{{ c.label }}</option></select></label><div class="dialog-actions"><button type="button" class="outline-button" :disabled="busy" @click="editing=null">Отмена</button><button class="primary-button" :disabled="busy">Сохранить</button></div></form></section></div></main></template>
